static inline uint8_t tpEvoNeededLevel(const TPEvolutionRule &r, unsigned mistakes) {
  unsigned n = r.level + mistakes; return n > 100 ? 100 : (uint8_t)n;
}
static inline bool tpEvoRuleReady(const TPEvolutionRule &r, unsigned level, unsigned bond, unsigned phase, bool hasClock, unsigned mistakes) {
  if (level < tpEvoNeededLevel(r, mistakes) || bond < r.bond) return false;
  if (r.time && !hasClock) return false;
  if (r.time==1 && phase==3) return false;
  if (r.time==2 && phase!=3) return false;
  if (r.time==3 && phase!=2) return false;
  return true;
}
